import{_ as n,W as i,s as d,u as l,ah as r,I as o,w as e,Z as p,A as a}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const v=JSON.parse('{"title":"如何在终端输入密码时显示星号 | LCTT x X-CMD","titleTemplate":false,"description":"如何在终端输入密码时显示星号 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在终端输入密码时显示星号 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在终端输入密码时显示星号 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180105 How To Display Asterisks When You Type Password In terminal","title":"如何在终端输入密码时显示星号","tag":"201802"},"relativePath":"201802/20180105 How To Display Asterisks When You Type Password In terminal.md","filePath":"[post].md"}'),c={name:"201802/20180105 How To Display Asterisks When You Type Password In terminal.md"};function u(h,s,m,w,g,b){const t=i("Link");return l(),d("div",null,[s[13]||(s[13]=r('<h1 id="如何在终端输入密码时显示星号" tabindex="-1">如何在终端输入密码时显示星号 <a class="header-anchor" href="#如何在终端输入密码时显示星号" aria-label="Permalink to 如何在终端输入密码时显示星号">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/01/Display-Asterisks-When-You-Type-Password-In-terminal-1-720x340.png" alt=""></p><p>当你在 Web 浏览器或任何 GUI 登录中输入密码时，密码会被标记成星号 <code>********</code> 或圆点符号 <code>•••••••••••••</code> 。这是内置的安全机制，以防止你附近的用户看到你的密码。但是当你在终端输入密码来执行任何 <code>sudo</code> 或 <code>su</code> 的管理任务时，你不会在输入密码的时候看见星号或者圆点符号。它不会有任何输入密码的视觉指示，也不会有任何光标移动，什么也没有。你不知道你是否输入了所有的字符。你只会看到一个空白的屏幕！</p><p>看看下面的截图。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/password-1.png" alt=""></p><p>正如你在上面的图片中看到的，我已经输入了密码，但没有任何指示（星号或圆点符号）。现在，我不确定我是否输入了所有密码。这个安全机制也可以防止你附近的人猜测密码长度。当然，这种行为可以改变。这是本指南要说的。这并不困难。请继续阅读。</p><h4 id="当你在终端输入密码时显示星号" tabindex="-1">当你在终端输入密码时显示星号 <a class="header-anchor" href="#当你在终端输入密码时显示星号" aria-label="Permalink to 当你在终端输入密码时显示星号">​</a></h4><p>要在终端输入密码时显示星号，我们需要在 <code>/etc/sudoers</code> 中做一些小修改。在做任何更改之前，最好备份这个文件。为此，只需运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp /etc/sudoers{,.bak}</span></span></code></pre></div><p>上述命令将 <code>/etc/sudoers</code> 备份成名为 <code>/etc/sudoers.bak</code>。你可以恢复它，以防万一在编辑文件后出错。</p><p>接下来，使用下面的命令编辑 <code>/etc/sudoers</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo visudo</span></span></code></pre></div><p>找到下面这行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Defaults env_reset</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/visudo-1.png" alt=""></p><p>在该行的末尾添加一个额外的单词 <code>,pwfeedback</code>，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Defaults env_reset,pwfeedback</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/visudo-1-1.png" alt=""></p><p>然后，按下 <code>CTRL + x</code> 和 <code>y</code> 保存并关闭文件。重新启动终端以使更改生效。</p><p>现在，当你在终端输入密码时，你会看到星号。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/visudo-2.png" alt=""></p><p>如果你对在终端输入密码时看不到密码感到不舒服，那么这个小技巧会有帮助。请注意，当你输入输入密码时其他用户就可以预测你的密码长度。如果你不介意，请按照上述方法进行更改，以使你的密码可见（当然，显示为星号！）。</p><p>现在就是这样了。还有更好的东西。敬请关注！</p><p>干杯!</p><hr>',25)),o("p",null,[s[1]||(s[1]=e("via: ")),p(t,{href:"https://www.ostechnix.com/display-asterisks-type-password-terminal/"},{default:a(()=>s[0]||(s[0]=[e("https://www.ostechnix.com/display-asterisks-type-password-terminal/")])),_:1})]),o("p",null,[s[5]||(s[5]=e("作者：")),p(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>s[2]||(s[2]=[e("SK")])),_:1}),s[6]||(s[6]=e(" 译者：")),p(t,{href:"https://github.com/geekpi"},{default:a(()=>s[3]||(s[3]=[e("geekpi")])),_:1}),s[7]||(s[7]=e(" 校对：")),p(t,{href:"https://github.com/wxy"},{default:a(()=>s[4]||(s[4]=[e("wxy")])),_:1})]),o("p",null,[s[10]||(s[10]=e("本文由 ")),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>s[8]||(s[8]=[e("LCTT")])),_:1}),s[11]||(s[11]=e(" 原创编译，")),p(t,{href:"https://linux.cn/"},{default:a(()=>s[9]||(s[9]=[e("Linux中国")])),_:1}),s[12]||(s[12]=e(" 荣誉推出"))])])}const x=n(c,[["render",u]]);export{v as __pageData,x as default};
